// =====================================================================

// RISC-V Opcodes (7 bits)
`define OPCODE_R_TYPE   7'b0110011
`define OPCODE_I_TYPE   7'b0010011
`define OPCODE_LW       7'b0000011
`define OPCODE_S_TYPE   7'b0100011
`define OPCODE_B_TYPE   7'b1100011
`define OPCODE_JAL      7'b1101111
`define OPCODE_JALR     7'b1100111

// Funct3 (3 bits)
`define FUNCT3_ADD_SUB  3'b000
`define FUNCT3_SLT      3'b010
`define FUNCT3_XOR      3'b100
`define FUNCT3_OR       3'b110
`define FUNCT3_AND      3'b111
`define FUNCT3_LW       3'b010
`define FUNCT3_SW       3'b010
`define FUNCT3_BEQ      3'b000
`define FUNCT3_BNE      3'b001
`define FUNCT3_BLT      3'b100
`define FUNCT3_BGE      3'b101

// Funct7 (7 bits)
`define FUNCT7_ADD      7'b0000000
`define FUNCT7_SUB      7'b0100000

// ALU Operations (internal encoding)
`define ALU_ADD     3'b000
`define ALU_SUB     3'b001
`define ALU_AND     3'b010
`define ALU_OR      3'b011
`define ALU_XOR     3'b100
`define ALU_SLT     3'b101 // Set Less Than (signed)

// NOP instruction (ADDI x0, x0, 0)
`define NOP_INST    32'h00000013 

// =====================================================================
// Internal Wires and Registers
// =====================================================================

// PC Register
reg [31:0] pc_reg;
wire [31:0] pc_plus_4;
wire [31:0] next_pc;

// Register File
reg [31:0] reg_file [0:31];
wire [4:0] rs1_addr_id;
wire [4:0] rs2_addr_id;
wire [4:0] rd_addr_wb;
wire [31:0] rs1_data_from_rf;
wire [31:0] rs2_data_from_rf;
wire [31:0] wb_wdata;
wire        wb_wen;

// Control Signals (from ID stage, propagated)
reg         id_regwrite;
reg         id_memread;
reg         id_memwrite;
reg         id_alu_src;  // 0: rs2, 1: immediate
reg         id_branch;
reg         id_jump;
reg  [2:0]  id_alu_op;

// Immediate values
wire [31:0] imm_i_type;
wire [31:0] imm_s_type;
wire [31:0] imm_b_type;
wire [31:0] imm_j_type;

// Hazard Control Signals
reg         stall;
reg         flush;
reg         branch_taken_ex; // Branch taken decision from EX stage

// =====================================================================
// Pipeline Registers
// =====================================================================

// IF/ID Register
reg [31:0] ifid_pc;
reg [31:0] ifid_inst;

// ID/EX Register
reg [31:0] idex_pc;
reg [31:0] idex_rs1_data;
reg [31:0] idex_rs2_data;
reg [4:0]  idex_rs1_addr;
reg [4:0]  idex_rs2_addr;
reg [4:0]  idex_rd_addr;
reg [31:0] idex_imm;
reg        idex_regwrite;
reg        idex_memread;
reg        idex_memwrite;
reg        idex_alu_src;
reg        idex_branch;
reg        idex_jump;
