// EX/MEM Register
reg [31:0] exmem_pc;
reg [31:0] exmem_alu_result;
reg [31:0] exmem_mem_wdata; // rs2_data (forwarded)
reg [4:0]  exmem_rd_addr;
reg        exmem_regwrite;
reg        exmem_memread;
reg        exmem_memwrite;

// MEM/WB Register
reg [31:0] memwb_pc;
reg [31:0] memwb_alu_result;
reg [31:0] memwb_mem_rdata;
reg [4:0]  memwb_rd_addr;
reg        memwb_regwrite;
reg        memwb_memread; // CRITICAL: MUST be declared as reg
    reg idex_inst;
    reg memwb_result;

// =====================================================================
// Stage 1: IF (Instruction Fetch)
// =====================================================================

assign imem_addr = pc_reg;
assign pc_plus_4 = pc_reg + 32'd4;

// PC Update Logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        pc_reg <= 32'h00000000; // REQ-9: Reset PC to 0
    end else if (stall) begin
        // PC holds its value
    end else begin
        pc_reg <= next_pc;
    end
end

// IF/ID Pipeline Register
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        ifid_pc   <= 32'h00000000;
        ifid_inst <= `NOP_INST; // Flush with NOP
    end else if (stall) begin
        // IF/ID holds its value
    end else if (flush) begin
        ifid_pc   <= pc_plus_4; // PC is already updated to branch target
        ifid_inst <= `NOP_INST; // REQ-7: Flush with NOP
    end else begin
        ifid_pc   <= pc_reg; // Store PC of fetched instruction
        ifid_inst <= imem_data;
    end
end

// Debug outputs
assign debug_pc   = pc_reg;
assign debug_inst = imem_data;

// =====================================================================
// Stage 2: ID (Instruction Decode)
// =====================================================================

// Instruction fields
wire [6:0] opcode  = ifid_inst[6:0];
wire [4:0] rd_addr = ifid_inst[11:7];
wire [2:0] funct3  = ifid_inst[14:12];
wire [4:0] rs1_addr = ifid_inst[19:15];
wire [4:0] rs2_addr = ifid_inst[24:20];
wire [6:0] funct7  = ifid_inst[31:25];

assign rs1_addr_id = rs1_addr;
assign rs2_addr_id = rs2_addr;

// Register File (REQ-1: x0 hardwired to 0, REQ-10: reset to 0)
integer i;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i < 32; i = i + 1) begin
            reg_file[i] <= 32'h00000000;
        end
    end else if (wb_wen) begin
        if (rd_addr_wb != 5'b00000) begin // REQ-1: Don't write to x0
            reg_file[rd_addr_wb] <= wb_wdata;
        end
    end
end

assign rs1_data_from_rf = (rs1_addr == 5'b00000) ? 32'h00000000 : reg_file[rs1_addr];
assign rs2_data_from_rf = (rs2_addr == 5'b00000) ? 32'h00000000 : reg_file[rs2_addr];

// Immediate Generator (REQ-8: Sign-extended)
assign imm_i_type = {{20{ifid_inst[31]}}, ifid_inst[31:20]};
assign imm_s_type = {{20{ifid_inst[31]}}, ifid_inst[31:25], ifid_inst[11:7]};
assign imm_b_type = {{20{ifid_inst[31]}}, ifid_inst[7], ifid_inst[30:25], ifid_inst[11:8], 1'b0};
assign imm_j_type = {{12{ifid_inst[31]}}, ifid_inst[19:12], ifid_inst[20], ifid_inst[30:21], 1'b0};

// Control Unit
always @(*) begin
    // Default values
    id_regwrite = 1'b0;
    id_memread  = 1'b0;
    id_memwrite = 1'b0;
    id_alu_src  = 1'b0; // Default to rs2
    id_branch   = 1'b0;
    id_jump     = 1'b0;
    id_alu_op   = `ALU_ADD; // Default ALU op

    case (opcode)
        `OPCODE_R_TYPE: begin // R-type: ADD, SUB, AND, OR, XOR, SLT
            id_regwrite = 1'b1;
            id_alu_src  = 1'b0; // rs2
            case (funct3)
                `FUNCT3_ADD_SUB: begin
                    if (funct7 == `FUNCT7_ADD) id_alu_op = `ALU_ADD;
                    else if (funct7 == `FUNCT7_SUB) id_alu_op = `ALU_SUB;
                    else id_alu_op = `ALU_ADD; // Default to ADD for unsupported funct7
                end
                `FUNCT3_SLT: id_alu_op = `ALU_SLT;
                `FUNCT3_XOR: id_alu_op = `ALU_XOR;
                `FUNCT3_OR:  id_alu_op = `ALU_OR;
                `FUNCT3_AND: id_alu_op = `ALU_AND;
                default: id_alu_op = `ALU_ADD; // Default for unsupported funct3
            endcase
        end
        `OPCODE_I_TYPE: begin // I-type: ADDI, SLTI, XORI, ORI, ANDI
            id_regwrite = 1'b1;
            id_alu_src  = 1'b1; // immediate
            case (funct3)
                `FUNCT3_ADD_SUB: id_alu_op = `ALU_ADD; // ADDI
                `FUNCT3_SLT:     id_alu_op = `ALU_SLT; // SLTI
                `FUNCT3_XOR:     id_alu_op = `ALU_XOR; // XORI
                `FUNCT3_OR:      id_alu_op = `ALU_OR;  // ORI
                `FUNCT3_AND:     id_alu_op = `ALU_AND; // ANDI
                default: id_alu_op = `ALU_ADD; // Default for unsupported funct3
            endcase
        end
        `OPCODE_LW: begin // LW
            id_regwrite = 1'b1;
            id_memread  = 1'b1;
            id_alu_src  = 1'b1; // immediate for address calculation
            id_alu_op   = `ALU_ADD; // Add base + offset
        end
        `OPCODE_S_TYPE: begin // SW
            id_memwrite = 1'b1;
            id_alu_src  = 1'b1; // immediate for address calculation
            id_alu_op   = `ALU_ADD; // Add base + offset
        end
        `OPCODE_B_TYPE: begin // B-type: BEQ, BNE, BLT, BGE
            id_branch   = 1'b1;
            id_alu_src  = 1'b0; // rs2 for comparison
            id_alu_op   = `ALU_SUB; // For comparison (rs1 - rs2)
        end
        `OPCODE_JAL: begin // JAL
            id_regwrite = 1'b1;
            id_jump     = 1'b1;
            id_alu_op   = `ALU_ADD; // Dummy ALU op, not used for JAL result
        end
        `OPCODE_JALR: begin // JALR
            id_regwrite = 1'b1;
            id_jump     = 1'b1;
            id_alu_src  = 1'b1; // immediate for JALR target calculation
            id_alu_op   = `ALU_ADD; // Add base + offset for JALR target
        end
        default: begin
            // NOP or unsupported instruction, all control signals remain default (0)
        end
    endcase
end

// ID/EX Pipeline Register
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        idex_pc         <= 32'h00000000;
        idex_rs1_data   <= 32'h00000000;
        idex_rs2_data   <= 32'h00000000;
        idex_rs1_addr   <= 5'b00000;
        idex_rs2_addr   <= 5'b00000;
        idex_rd_addr    <= 5'b00000;
        idex_imm        <= 32'h00000000;
        idex_regwrite   <= 1'b0;
        idex_memread    <= 1'b0;
        idex_memwrite   <= 1'b0;
        idex_alu_src    <= 1'b0;
        idex_branch     <= 1'b0;
        idex_jump       <= 1'b0;
        idex_alu_op     <= `ALU_ADD;
    end else if (flush) begin // REQ-7: Flush ID/EX
        idex_pc         <= 32'h00000000;
        idex_rs1_data   <= 32'h00000000;
        idex_rs2_data   <= 32'h00000000;
        idex_rs1_addr   <= 5'b00000;
        idex_rs2_addr   <= 5'b00000;
        idex_rd_addr    <= 5'b00000;
        idex_imm        <= 32'h00000000;
        idex_regwrite   <= 1'b0;
        idex_memread    <= 1'b0;
        idex_memwrite   <= 1'b0;
        idex_alu_src    <= 1'b0;
        idex_branch     <= 1'b0;
        idex_jump       <= 1'b0;
        idex_alu_op     <= `ALU_ADD;
    end else begin
        idex_pc         <= ifid_pc;
        idex_rs1_data   <= rs1_data_from_rf;
        idex_rs2_data   <= rs2_data_from_rf;
        idex_rs1_addr   <= rs1_addr;
        idex_rs2_addr   <= rs2_addr;
        idex_rd_addr    <= rd_addr;
        idex_regwrite   <= id_regwrite;
        idex_memread    <= id_memread;
        idex_memwrite   <= id_memwrite;
        idex_alu_src    <= id_alu_src;
        idex_branch     <= id_branch;
        idex_jump       <= id_jump;
        idex_alu_op     <= id_alu_op;

        // Select correct immediate based on instruction type
        case (opcode)
            `OPCODE_I_TYPE, `OPCODE_LW, `OPCODE_JALR: idex_imm <= imm_i_type;
            `OPCODE_S_TYPE: idex_imm <= imm_s_type;
            `OPCODE_B_TYPE: idex_imm <= imm_b_type;
            `OPCODE_JAL:    idex_imm <= imm_j_type;
            default:        idex_imm <= 32'h00000000;
        endcase
    end
end

// =====================================================================
// Stage 3: EX (Execute)
// =====================================================================

// Forwarding Unit (REQ-4, REQ-5)
reg [31:0] forward_a;
reg [31:0] forward_b;

always @(*) begin
    forward_a = idex_rs1_data;
    forward_b = idex_rs2_data;

    // Forward from EX/MEM stage to ALU input A
    if (exmem_regwrite && (exmem_rd_addr != 5'b00000) && (exmem_rd_addr == idex_rs1_addr)) begin
        forward_a = exmem_alu_result;
    end
    // Forward from MEM/WB stage to ALU input A
    if (memwb_regwrite && (memwb_rd_addr != 5'b00000) && (memwb_rd_addr == idex_rs1_addr)) begin
        forward_a = memwb_memread ? memwb_mem_rdata : memwb_alu_result; // REQ-5: memwb_result
    end

    // Forward from EX/MEM stage to ALU input B
    if (exmem_regwrite && (exmem_rd_addr != 5'b00000) && (exmem_rd_addr == idex_rs2_addr)) begin
        forward_b = exmem_alu_result;
    end
    // Forward from MEM/WB stage to ALU input B
    if (memwb_regwrite && (memwb_rd_addr != 5'b00000) && (memwb_rd_addr == idex_rs2_addr)) begin
        forward_b = memwb_memread ? memwb_mem_rdata : memwb_alu_result; // REQ-5: memwb_result
    end
end

// ALU Inputs
wire [31:0] alu_operand_a = forward_a;
wire [31:0] alu_operand_b = idex_alu_src ? idex_imm : forward_b;

// ALU Logic
wire [31:0] alu_result_ex;
wire        alu_zero_ex;
wire        alu_less_ex; // for signed comparison

always @(*) begin
    alu_result_ex = 32'h00000000;
    alu_zero_ex   = 1'b0;
    alu_less_ex   = 1'b0;

    case (idex_alu_op)
        `ALU_ADD: alu_result_ex = alu_operand_a + alu_operand_b;
        `ALU_SUB: alu_result_ex = alu_operand_a - alu_operand_b;
        `ALU_AND: alu_result_ex = alu_operand_a & alu_operand_b;
        `ALU_OR:  alu_result_ex = alu_operand_a | alu_operand_b;
        `ALU_XOR: alu_result_ex = alu_operand_a ^ alu_operand_b;
        `ALU_SLT: begin // REQ-2: Signed comparison
            if ($signed(alu_operand_a) < $signed(alu_operand_b)) begin
                alu_result_ex = 32'd1;
                alu_less_ex = 1'b1;
            end else begin
                alu_result_ex = 32'd0;
                alu_less_ex = 1'b0;
            end
        end
        default: alu_result_ex = 32'h00000000;
    endcase

    if (alu_result_ex == 32'h00000000) alu_zero_ex = 1'b1;
end

// Branch Target Address Calculation
wire [31:0] branch_target_address = idex_pc + idex_imm;

// Jump Target Address Calculation
wire [31:0] jump_target_address = idex_pc + idex_imm;
wire [31:0] jalr_target_address = (alu_operand_a + idex_imm) & 32'hFFFFFFFE; // JALR target LSB is 0

// Branch Condition Evaluation
reg branch_cond_met;
always @(*) begin
    branch_cond_met = 1'b0;
    if (idex_branch) begin
        case (funct3) // funct3 is from ifid_inst, but we need it from idex_inst
            `FUNCT3_BEQ: branch_cond_met = alu_zero_ex;
            `FUNCT3_BNE: branch_cond_met = ~alu_zero_ex;
            `FUNCT3_BLT: branch_cond_met = alu_less_ex;
            `FUNCT3_BGE: branch_cond_met = ~alu_less_ex; // (rs1 >= rs2) is !(rs1 < rs2)
            default: branch_cond_met = 1'b0;
        endcase
    end
end

// Branch Taken Decision and Flush (REQ-7)
always @(*) begin
    branch_taken_ex = 1'b0;
    if (idex_branch && branch_cond_met) begin
        branch_taken_ex = 1'b1;
    end else if (idex_jump) begin // JAL or JALR
        branch_taken_ex = 1'b1;
    end
end

// EX/MEM Pipeline Register
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        exmem_pc         <= 32'h00000000;
        exmem_alu_result <= 32'h00000000;
        exmem_mem_wdata  <= 32'h00000000;
        exmem_rd_addr    <= 5'b00000;
        exmem_regwrite   <= 1'b0;
        exmem_memread    <= 1'b0;
        exmem_memwrite   <= 1'b0;
    end else begin
        exmem_pc         <= idex_pc;
        exmem_alu_result <= alu_result_ex;
        exmem_mem_wdata  <= forward_b; // rs2_data (potentially forwarded)
        exmem_rd_addr    <= idex_rd_addr;
        exmem_regwrite   <= idex_regwrite;
        exmem_memread    <= idex_memread;
        exmem_memwrite   <= idex_memwrite;
    end
end

// =====================================================================
// Stage 4: MEM (Memory Access)
// =====================================================================

// Data Memory Interface (D2: Word-aligned access)
assign dmem_addr  = exmem_alu_result & 32'hFFFFFFFC; // Force word alignment
assign dmem_wdata = exmem_mem_wdata;
assign dmem_wen   = exmem_memwrite;
assign dmem_be    = 4'b1111; // Always full word for RV32I LW/SW

// MEM/WB Pipeline Register
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        memwb_pc         <= 32'h00000000;
        memwb_alu_result <= 32'h00000000;
        memwb_mem_rdata  <= 32'h00000000;
        memwb_rd_addr    <= 5'b00000;
        memwb_regwrite   <= 1'b0;
        memwb_memread    <= 1'b0; // CRITICAL: MUST be initialized
    end else begin
        memwb_pc         <= exmem_pc;
        memwb_alu_result <= exmem_alu_result;
        memwb_mem_rdata  <= dmem_rdata;
        memwb_rd_addr    <= exmem_rd_addr;
        memwb_regwrite   <= exmem_regwrite;
        memwb_memread    <= exmem_memread; // CRITICAL: Propagate
    end
end

// =====================================================================
// Stage 5: WB (Write Back)
// =====================================================================

assign rd_addr_wb = memwb_rd_addr;
assign wb_wen     = memwb_regwrite;

// Select data to write back (memory data or ALU result)
assign wb_wdata = memwb_memread ? memwb_mem_rdata : memwb_alu_result;

// =====================================================================
// Hazard Unit (Stall and Flush Logic)
// =====================================================================

// Load-Use Hazard Detection (REQ-6)
wire load_use_hazard;
assign load_use_hazard = idex_memread && (idex_rd_addr != 5'b00000) &&
                         ((idex_rd_addr == rs1_addr_id) || (idex_rd_addr == rs2_addr_id));

always @(*) begin
    stall = 1'b0;
    if (load_use_hazard) begin
        stall = 1'b1;
    end
end

// Control Hazard Flush (REQ-7)
always @(*) begin
    flush = 1'b0;
    if (branch_taken_ex) begin
        flush = 1'b1;
    end
end

// Next PC selection
always @(*) begin
    next_pc = pc_plus_4; // Default to PC + 4

    if (branch_taken_ex) begin
        if (idex_jump) begin // JAL or JALR
            if (idex_alu_op == `ALU_ADD && idex_alu_src == 1'b1) begin // JALR
                next_pc = jalr_target_address;
            end else begin // JAL
                next_pc = jump_target_address;
            end
        end else if (idex_branch) begin // Branch
            next_pc = branch_target_address;
        end
    end
end

endmodule